"""Independent SG-inspired *structure*, not SG wording or validated legal provisions."""

def conditional_terms(p, language='EN'):
    """Generate family-specific indicative contractual descriptions from actual payoff inputs."""
    fr=language=='FR'; pct=lambda x:f'{x:.2%}'
    f=p.family if hasattr(p,'family') else 'Phoenix Autocall'
    if f=='Phoenix Autocall':
        rows=[('Observation and coupon test','Constatation et condition de coupon',f'{p.periods} observations; coupon {pct(p.coupon_rate/p.frequency)} of notional when ratio ≥ {pct(p.coupon_barrier)}; no memory.',f'{p.periods} observations ; coupon de {pct(p.coupon_rate/p.frequency)} du nominal si ratio ≥ {pct(p.coupon_barrier)} ; sans mémoire.'),('Automatic redemption','Remboursement automatique',f'From observation {p.first_call}, before maturity: ratio ≥ {pct(p.call_barrier)} ⇒ principal repaid; subsequent payments cease.',f'À partir de l’observation {p.first_call}, avant échéance : ratio ≥ {pct(p.call_barrier)} ⇒ remboursement du nominal et arrêt des flux ultérieurs.'),('Final European protection','Protection européenne finale',f'Absent early call: ratio ≥ {pct(p.protection_barrier)} ⇒ 100% principal; otherwise principal × final ratio.',f'Sans rappel : ratio ≥ {pct(p.protection_barrier)} ⇒ 100 % du nominal ; sinon nominal × ratio final.')]
    elif f=='Athena Autocall':
        rows=[('Accrued contingent gain','Gain conditionnel cumulé',f'Simple gain {pct(p.coupon_rate)} per elapsed year, only on qualifying redemption; no periodic coupons.',f'Gain simple de {pct(p.coupon_rate)} par année écoulée, uniquement en cas de remboursement éligible ; sans coupon périodique.'),('Automatic redemption','Remboursement automatique',f'From observation {p.first_call}: ratio ≥ {pct(p.call_barrier)} ⇒ principal plus accrued gain.',f'À partir de l’observation {p.first_call} : ratio ≥ {pct(p.call_barrier)} ⇒ nominal augmenté du gain cumulé.'),('Final downside test','Test final de baisse',f'If not called and final ratio < {pct(p.protection_barrier)}, principal × final ratio; otherwise apply final call/gain rules.',f'Sans rappel et si ratio final < {pct(p.protection_barrier)}, nominal × ratio final ; sinon règles finales de rappel et de gain.')]
    elif f=='European Option':
        rows=[('Exercise and settlement','Exercice et règlement','European exercise at maturity only; illustrative cash settlement, not physical delivery.','Exercice européen à échéance uniquement ; règlement en espèces illustratif, sans livraison physique.'),('Final payoff','Paiement final',f'{p.option_type}: notional × max({"final ratio − strike" if p.option_type=="Call" else "strike − final ratio"}, 0); strike {pct(p.strike)}.',f'{p.option_type} : nominal × max({"ratio final − strike" if p.option_type=="Call" else "strike − ratio final"}, 0) ; strike {pct(p.strike)}.'),('Premium at risk','Prime exposée','Premium paid is separate from payoff and may be lost in full.','La prime versée est distincte du paiement final et peut être intégralement perdue.')]
    elif f=='Capital Protected Note':
        rows=[('Contractual maturity floor','Plancher contractuel à échéance',f'{pct(p.protection)} of principal at scheduled maturity, conditional on hypothetical issuer performance.',f'{pct(p.protection)} du nominal à échéance, sous réserve de l’exécution par un émetteur hypothétique.'),('Positive participation','Participation à la hausse',f'Additional amount: notional × {pct(p.participation)} × max(final ratio − {pct(p.strike)}, 0).',f'Montant additionnel : nominal × {pct(p.participation)} × max(ratio final − {pct(p.strike)}, 0).'),('Early disposal','Cession avant échéance','No floor applies to secondary-market sale value.','Le plancher ne s’applique pas au prix de revente avant échéance.')]
    elif f=='Credit Linked Note':
        rows=[('Reference entity','Entité de référence',p.reference_entity,p.reference_entity),('Running coupon','Coupon courant',f'{pct(p.coupon_rate)} per annum until modelled default or maturity.',f'{pct(p.coupon_rate)} par an jusqu’au défaut modélisé ou à échéance.'),('Credit-event settlement','Règlement après événement de crédit',f'Illustrative recovery-at-default: {pct(p.recovery)} of principal; coupons cease; credit-event definitions are not implemented.',f'Recouvrement illustratif au défaut : {pct(p.recovery)} du nominal ; arrêt des coupons ; définitions des événements de crédit non implémentées.')]
    else:raise ValueError(f)
    return [(b if fr else a,d if fr else c) for a,b,c,d in rows]

def important_information(family, kind, language='EN'):
    fr=language=='FR'
    if family=='Credit Linked Note':
        return ('La détermination d’un événement de crédit, la succession de l’entité de référence et le montant de règlement nécessitent des stipulations définitives. Aucun mécanisme ISDA ou de règlement par enchères n’est implémenté.' if fr else 'Credit-event determination, reference-entity succession and settlement amounts require definitive contractual provisions. No ISDA determination or auction settlement is implemented.')
    return ('La valeur de revente avant échéance peut différer sensiblement du montant de remboursement contractuel. Aucune liquidité secondaire, commission, restriction de commercialisation ou obligation de rachat n’est stipulée.' if fr else 'A sale before scheduled maturity may realise materially less than the contractual redemption amount. No secondary-market liquidity, fees, selling restrictions or repurchase commitment is specified.')
